"""Check for unused imports in the changed modules."""

import ast
import re
from pathlib import Path

FILES = [
    "sqlit/domains/query/app/alerts.py",
    "sqlit/domains/query/completion/core.py",
    "sqlit/domains/query/app/multi_statement.py",
    "sqlit/domains/query/ui/mixins/query_execution.py",
    "sqlit/domains/query/editing/sql_lexer.py",
    "tests/unit/test_sql_lexer.py",
    "tests/unit/test_multi_statement.py",
]

for path in FILES:
    src = Path(path).read_text()
    tree = ast.parse(src)
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                imported.add((alias.asname or alias.name).split(".")[0])
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                if alias.name != "annotations":
                    imported.add(alias.asname or alias.name)
    for name in sorted(imported):
        uses = len(re.findall(r"\b" + re.escape(name) + r"\b", src))
        if uses <= 1:
            print(f"{path}: unused import -> {name}")
print("done")

