@dataclass
class ProcessQueryOutcome:
    """Outcome for a process-executed query."""

    result: QueryResult | NonQueryResult | None
    elapsed_ms: float
    cancelled: bool = False
    error: str | None = None


class ProcessWorkerClient:
    """Runs queries in a separate process."""

    def __init__(self) -> None:
        self._conn: Connection | None = None
        self._process = None
        try:
            self._start_with_context(get_context("spawn"))
        except Exception as exc:
            self._maybe_fallback_start(exc)
        self._send_lock = threading.Lock()
        self._execute_lock = threading.Lock()
        self._next_id = 1
        self._closed = False
        self._current_id: int | None = None
        if self._conn is None or self._process is None:
            raise RuntimeError("Failed to start process worker.")

    def _start_with_context(self, ctx: Any) -> None:
        parent_conn, child_conn = ctx.Pipe(duplex=True)
        self._conn = parent_conn
        self._process = ctx.Process(
            target=run_process_worker,
            args=(child_conn,),
            daemon=True,
        )
        self._process.start()

    def _maybe_fallback_start(self, error: Exception) -> None:
        if not isinstance(error, ValueError):
            raise error
        message = str(error)
        if "fds_to_keep" not in message:
            raise error
        if os.name != "posix" or sys.platform.startswith("win"):
            raise error
        # macOS (especially Tahoe 26+) aborts in the child whenever a forked
        # process touches CoreFoundation / Security.framework / os_log —
        # which happens inside psycopg, getaddrinfo, and many other stdlib
        # paths. Forking here causes hard segfaults (issue #189), so we
        # surface the spawn failure and let the caller fall back to
        # in-process execution.
        if sys.platform == "darwin":
            raise error
        try:
            self._start_with_context(get_context("fork"))
        except Exception:
            raise error

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            self._send({"type": "shutdown"})
        except Exception:
            pass
        try:
            if self._conn is not None:
                self._conn.close()
        except Exception:
            pass
        if self._process is not None:
