"""Regression tests for Oracle trailing statement terminator handling."""

from __future__ import annotations

from unittest.mock import MagicMock

from sqlit.domains.connections.providers.oracle.adapter import (
    OracleAdapter,
    strip_trailing_terminator,
)


class TestStripTrailingTerminator:
    """Test the Oracle-specific trailing terminator stripping."""

    def test_strips_trailing_semicolon(self):
        assert strip_trailing_terminator("ALTER SESSION SET EDITION = V0;") == (
            "ALTER SESSION SET EDITION = V0"
        )

    def test_strips_trailing_semicolon_with_trailing_whitespace(self):
        assert strip_trailing_terminator("SELECT 1 FROM DUAL;  \n") == "SELECT 1 FROM DUAL"

    def test_leaves_query_without_semicolon_unchanged(self):
        assert strip_trailing_terminator("SELECT 1 FROM DUAL") == "SELECT 1 FROM DUAL"

    def test_leaves_plsql_block_terminator_intact(self):
        """PL/SQL blocks require the trailing "END;" - stripping it breaks them."""
        block = "BEGIN\n  NULL;\nEND;"
        assert strip_trailing_terminator(block) == block

    def test_leaves_plsql_block_with_label_intact(self):
        block = "BEGIN\n  NULL;\nEND my_label;"
        assert strip_trailing_terminator(block) == block

    def test_leaves_procedure_body_intact(self):
        body = "CREATE OR REPLACE PROCEDURE p AS\nBEGIN\n  NULL;\nEND;"
        assert strip_trailing_terminator(body) == body

    def test_strips_semicolon_after_end_keyword_as_column(self):
        """A column named "end" is not a PL/SQL terminator."""
        assert strip_trailing_terminator('SELECT "end" FROM t;') == 'SELECT "end" FROM t'

    def test_preserves_semicolon_inside_string_literal(self):
        assert strip_trailing_terminator("SELECT 'a;b' FROM t;") == "SELECT 'a;b' FROM t"


class TestOracleAdapterExecution:
    """Test that the adapter strips the terminator before hitting the driver."""

    def _adapter_and_cursor(self):
        adapter = OracleAdapter()
        conn = MagicMock()
        cursor = MagicMock()
        cursor.description = None
        cursor.rowcount = 0
        conn.cursor.return_value = cursor
        return adapter, conn, cursor

    def test_execute_non_query_strips_terminator(self):
        adapter, conn, cursor = self._adapter_and_cursor()
        adapter.execute_non_query(conn, "ALTER SESSION SET EDITION = V0;")
        cursor.execute.assert_called_once_with("ALTER SESSION SET EDITION = V0")

    def test_execute_query_strips_terminator(self):
        adapter, conn, cursor = self._adapter_and_cursor()
        adapter.execute_query(conn, "SELECT 1 FROM DUAL;")
        cursor.execute.assert_called_once_with("SELECT 1 FROM DUAL")

    def test_execute_non_query_preserves_plsql_block(self):
        adapter, conn, cursor = self._adapter_and_cursor()
        block = "BEGIN\n  NULL;\nEND;"
        adapter.execute_non_query(conn, block)
        cursor.execute.assert_called_once_with(block)

